import{_ as e,c as a,o as i,a0 as r}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Hojas de ejercicios de juegos mentales","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/es/exercise-worksheets.md","filePath":"public/downloads/es/exercise-worksheets.md"}');const o=e({name:"public/downloads/es/exercise-worksheets.md"},[["render",function(e,t,o,_,n,l){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="hojas-de-ejercicios-de-juegos-mentales" tabindex="-1">Hojas de ejercicios de juegos mentales <a class="header-anchor" href="#hojas-de-ejercicios-de-juegos-mentales" aria-label="Permalink to &quot;Hojas de ejercicios de juegos mentales&quot;">​</a></h1><p><strong>Academia de Petanca - Ejercicios Prácticos</strong></p><hr><h2 id="ejercicio-1-reflexion-del-estado-de-flujo" tabindex="-1">Ejercicio 1: Reflexión del estado de flujo <a class="header-anchor" href="#ejercicio-1-reflexion-del-estado-de-flujo" aria-label="Permalink to &quot;Ejercicio 1: Reflexión del estado de flujo&quot;">​</a></h2><h3 id="¿cuando-has-experimentado-el-flujo" tabindex="-1">¿Cuándo has experimentado el flujo? <a class="header-anchor" href="#¿cuando-has-experimentado-el-flujo" aria-label="Permalink to &quot;¿Cuándo has experimentado el flujo?&quot;">​</a></h3><p>Piensa en una ocasión en la que jugaste tu mejor petanca:</p><p><strong>Describe la situación:</strong></p><ul><li>¿Qué torneo/juego fue?</li><li>¿Cuales eran las condiciones?</li><li>¿Con quién estabas jugando?</li></ul><hr><hr><p><strong>¿Cómo te sentiste?</strong></p><ul><li>¿Cuál era tu estado mental?</li><li>¿Cómo se sintió el tiempo?</li><li>¿En qué estabas pensando (o no pensando)?</li></ul><hr><hr><p><strong>¿Qué te ayudó a llegar ahí?</strong></p><ul><li>¿Qué hiciste antes del partido?</li><li>¿Qué tuvo de diferente ese día?</li><li>¿Puedes recrear alguna de esas condiciones?</li></ul><hr><hr><hr><h2 id="ejercicio-2-inventario-del-critico-interno" tabindex="-1">Ejercicio 2: Inventario del crítico interno <a class="header-anchor" href="#ejercicio-2-inventario-del-critico-interno" aria-label="Permalink to &quot;Ejercicio 2: Inventario del crítico interno&quot;">​</a></h2><h3 id="identifica-a-tu-critico-interno" tabindex="-1">Identifica a tu crítico interno <a class="header-anchor" href="#identifica-a-tu-critico-interno" aria-label="Permalink to &quot;Identifica a tu crítico interno&quot;">​</a></h3><p><strong>¿Qué dice tu crítico interno?</strong></p><p>Enumere entre 3 y 5 pensamientos críticos comunes que tiene durante la competencia:</p><ol><li><hr></li><li><hr></li><li><hr></li><li><hr></li><li><hr></li></ol><p><strong>¿Cuando aparece?</strong></p><ul><li>¿Después de los errores? □</li><li>¿Antes de tomas importantes? □</li><li>¿Cuándo juegas contra oponentes fuertes? □</li><li>¿Cuándo están mirando los compañeros de equipo? □</li><li>Otro: _______________________________________________</li></ul><hr><h2 id="ejercicio-3-practica-de-reencuadre" tabindex="-1">Ejercicio 3: Práctica de reencuadre <a class="header-anchor" href="#ejercicio-3-practica-de-reencuadre" aria-label="Permalink to &quot;Ejercicio 3: Práctica de reencuadre&quot;">​</a></h2><h3 id="transformar-al-critico-en-entrenador" tabindex="-1">Transformar al crítico en entrenador <a class="header-anchor" href="#transformar-al-critico-en-entrenador" aria-label="Permalink to &quot;Transformar al crítico en entrenador&quot;">​</a></h3><p><strong>Para cada pensamiento del Crítico Interno, escribe un replanteamiento del Coach Interno:</strong></p><table tabindex="0"><thead><tr><th>Crítico Interno</th><th>Entrenador Interno</th></tr></thead><tbody><tr><td>Ejemplo: &quot;Siempre me equivoco bajo presión&quot;</td><td>&quot;Ya he tenido éxito bajo presión antes, puedo hacerlo de nuevo&quot;</td></tr><tr><td>1. _________________________</td><td>_________________________</td></tr><tr><td>2. _________________________</td><td>_________________________</td></tr><tr><td>3. _________________________</td><td>_________________________</td></tr></tbody></table><p><strong>Practica decir esto en voz alta</strong></p><hr><h2 id="ejercicio-4-diseno-de-rutina-previa-al-disparo" tabindex="-1">Ejercicio 4: Diseño de rutina previa al disparo <a class="header-anchor" href="#ejercicio-4-diseno-de-rutina-previa-al-disparo" aria-label="Permalink to &quot;Ejercicio 4: Diseño de rutina previa al disparo&quot;">​</a></h2><h3 id="crea-tu-rutina-personal" tabindex="-1">Crea tu rutina personal <a class="header-anchor" href="#crea-tu-rutina-personal" aria-label="Permalink to &quot;Crea tu rutina personal&quot;">​</a></h3><p>Diseña una rutina de 4 pasos antes de disparar que funcione para ti:</p><p><strong>Paso 1: Visualizar</strong></p><ul><li>¿Qué exactamente visualizarás?</li><li>¿Cuánto tiempo (2-3 segundos)?</li></ul><hr><p><strong>Paso 2: Respira</strong></p><ul><li>¿Una respiración profunda o tres?</li><li>¿Algún patrón específico?</li></ul><hr><p><strong>Paso 3: Anclaje</strong></p><ul><li>¿Qué ancla física utilizarás?</li><li>¿Tocar la bola? ¿Posición específica?</li></ul><hr><p><strong>Paso 4: Ejecutar</strong></p><ul><li>¿Cuál es tu señal mental?</li><li>¿&quot;Confianza&quot; / &quot;Flujo&quot; / &quot;Ir&quot;?</li></ul><hr><p><strong>Practica esta rutina 10 veces hoy</strong></p><hr><h2 id="ejercicio-5-factores-desencadenantes-de-presion" tabindex="-1">Ejercicio 5: Factores desencadenantes de presión <a class="header-anchor" href="#ejercicio-5-factores-desencadenantes-de-presion" aria-label="Permalink to &quot;Ejercicio 5: Factores desencadenantes de presión&quot;">​</a></h2><h3 id="identifique-sus-puntos-de-presion" tabindex="-1">Identifique sus puntos de presión <a class="header-anchor" href="#identifique-sus-puntos-de-presion" aria-label="Permalink to &quot;Identifique sus puntos de presión&quot;">​</a></h3><p>¿Qué situaciones te generan presión?</p><p>Califica cada uno del 1 (sin presión) al 10 (presión extrema):</p><ul><li>Jugando contra oponentes fuertes: ___/10</li><li>Partidos importantes del torneo: ___/10</li><li>Puntuación empatada, tiro final: ___/10</li><li>Después de cometer un error: ___/10</li><li>Cuando los compañeros de equipo están mirando: ___/10</li><li>Cuando estoy jugando mal: ___/10</li><li>Otro: _________________________ ___/10</li></ul><p><strong>Para su disparador con mayor calificación:</strong></p><p>¿Qué sensaciones físicas notas?</p><hr><p>¿Qué pensamientos aparecen?</p><hr><p>¿Qué técnica utilizarás?</p><ul><li>[ ] Reinicio de 3 respiraciones</li><li>[ ] Rutina previa al disparo</li><li>[ ] Reencuadre</li><li>[ ] Otro: _____________________</li></ul><hr><h2 id="ejercicio-6-practica-de-cambio-de-modo" tabindex="-1">Ejercicio 6: Práctica de cambio de modo <a class="header-anchor" href="#ejercicio-6-practica-de-cambio-de-modo" aria-label="Permalink to &quot;Ejercicio 6: Práctica de cambio de modo&quot;">​</a></h2><h3 id="planificacion-vs-ejecucion" tabindex="-1">Planificación vs. Ejecución <a class="header-anchor" href="#planificacion-vs-ejecucion" aria-label="Permalink to &quot;Planificación vs. Ejecución&quot;">​</a></h3><p><strong>Practica el cambio:</strong></p><p><strong>Fase de planificación (antes de la toma):</strong></p><ul><li>¿Qué necesito analizar?</li><li>¿Cual es mi estrategia?</li><li>¿Qué tiro elegiré?</li></ul><p><strong>Fase de ejecución (durante el disparo):</strong></p><ul><li>Despeja tu mente</li><li>Confía en tu cuerpo</li><li>Déjalo pasar</li></ul><p><strong>Ejercicio de práctica:</strong></p><p>Haz 5 tiros de práctica. Para cada uno:</p><ol><li>Dedica 10 segundos al modo de planificación (analizar, decidir)</li><li>Tome 3 respiraciones para cambiar de modo</li><li>Ejecutar en modo de flujo (sin pensar)</li></ol><p><strong>Reflexión:</strong></p><ul><li>¿Podrías sentir la diferencia entre los modos?</li><li>¿El cambio fue claro?</li><li>¿Qué modo te resulta más difícil?</li></ul><hr><hr><hr><h2 id="ejercicio-7-plan-de-practica-semanal" tabindex="-1">Ejercicio 7: Plan de práctica semanal <a class="header-anchor" href="#ejercicio-7-plan-de-practica-semanal" aria-label="Permalink to &quot;Ejercicio 7: Plan de práctica semanal&quot;">​</a></h2><h3 id="el-enfoque-de-esta-semana" tabindex="-1">El enfoque de esta semana <a class="header-anchor" href="#el-enfoque-de-esta-semana" aria-label="Permalink to &quot;El enfoque de esta semana&quot;">​</a></h3><p><strong>Elige UNA técnica para practicar:</strong></p><ul><li>[ ] Reinicio de 3 respiraciones después de cada error</li><li>[ ] Rutina previa al lanzamiento en cada lanzamiento</li><li>[ ] Reformular un pensamiento del Crítico Interno por sesión</li><li>[ ] Cambio de modo de práctica</li></ul><p><strong>Práctica diaria:</strong></p><table tabindex="0"><thead><tr><th>Día</th><th>Actividad práctica</th><th>Duración</th><th>Notas</th></tr></thead><tbody><tr><td>lunes</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>martes</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Mié</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Jue</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>viernes</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>sábado</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sol</td><td>________________</td><td>___min</td><td>________________</td></tr></tbody></table><hr><h2 id="ejercicio-8-seguimiento-del-progreso" tabindex="-1">Ejercicio 8: Seguimiento del progreso <a class="header-anchor" href="#ejercicio-8-seguimiento-del-progreso" aria-label="Permalink to &quot;Ejercicio 8: Seguimiento del progreso&quot;">​</a></h2><h3 id="reflexion-de-fin-de-semana" tabindex="-1">Reflexión de fin de semana <a class="header-anchor" href="#reflexion-de-fin-de-semana" aria-label="Permalink to &quot;Reflexión de fin de semana&quot;">​</a></h3><p><strong>¿Qué practicaste esta semana?</strong></p><hr><p><strong>¿Qué notaste?</strong></p><hr><hr><p><strong>¿Qué funcionó bien?</strong></p><hr><hr><p><strong>¿Qué fue lo más desafiante?</strong></p><hr><hr><p><strong>¿Qué continuarás la próxima semana?</strong></p><hr><hr><p><strong>¿Qué vas a ajustar?</strong></p><hr><hr><hr><h2 id="proximos-pasos" tabindex="-1">Próximos pasos <a class="header-anchor" href="#proximos-pasos" aria-label="Permalink to &quot;Próximos pasos&quot;">​</a></h2><h3 id="continua-tu-desarrollo" tabindex="-1">Continúa tu desarrollo <a class="header-anchor" href="#continua-tu-desarrollo" aria-label="Permalink to &quot;Continúa tu desarrollo&quot;">​</a></h3><p><strong>Recursos en carreau.app:</strong></p><ul><li>Plantilla de objetivos: estructura tu desarrollo a largo plazo</li><li>Plantilla de diario: seguimiento del progreso diario</li><li>La Zona - Profundización en los estados de flujo</li><li>Fortalecimiento mental: gestión avanzada de la presión</li></ul><p><strong>Sigue practicando:</strong></p><ul><li>Las habilidades mentales necesitan un entrenamiento constante</li><li>Empieza poco a poco y construye gradualmente</li><li>Sigue tu progreso</li><li>Celebrar las mejoras</li></ul><hr><p><em>Academia de Petanca - Desarrollo de jugadores de élite</em><em>carreau.app</em></p>',113)])])}]]);export{t as __pageData,o as default};
